   {"no":1,"affix":"ber-","type":"前缀","func":"构成动词：拥有/处于/进行某活动","rule":"ber- + 词根；词根首字母为 r 时省一个 r","derivs":[{"root":"negosiasi","der":"bernegosiasi","zh":"进行谈判"},{"root":"runding","der":"berunding","zh":"磋商"},{"root":"diskusi","der":"berdiskusi","zh":"讨论"},{"root":"temu","der":"bertemu","zh":"会面"}],"examples":[{"id":"Kedua pihak bernegosiasi secara terbuka sejak pagi.","cn":"双方自上午起坦诚谈判。"},{"id":"Kita berunding dengan itikad baik untuk mencapai hasil adil.","cn":"我们本着诚意的原则磋商以求公平结果。"}],"link":"ber-"},
   {"no":2,"affix":"be-","type":"前缀（ber- 变体）","func":"ber- 在特定词根前的缩略形式，构成动词","rule":"be- + 词根；适用词根无统一规律，需整词记忆","derivs":[{"root":"kerja","der":"bekerja","zh":"工作"},{"root":"kerja sama","der":"bekerja sama","zh":"合作"}],"examples":[{"id":"Kedua perusahaan telah bekerja sama selama lima tahun.","cn":"两家公司合作已达五年。"},{"id":"Tim kami siap bekerja sama dengan pihak audit.","cn":"我们团队准备好与审计方合作。"}],"link":"be-"},
   {"no":3,"affix":"meN-","type":"前缀","func":"及物动词标记：把……做了","rule":"meN- 同化：p/b→mem-，t/d→men-，k/g/h/元音→meng-，s→meny-，l 及辅音丛→me-","derivs":[{"root":"tawar","der":"menawar","zh":"讨价还价"},{"root":"undang","der":"mengundang","zh":"邀请"},{"root":"siap","der":"menyiapkan","zh":"准备"},{"root":"balas","der":"membalas","zh":"回复"}],"examples":[{"id":"Kami mengundang tiga penawar ke rapat pembukaan.","cn":"我们邀请了三家报价方参加开幕会议。"},{"id":"Tim hukum sedang menyiapkan dokumen tambahan.","cn":"法务团队正在准备补充文件。"}],"link":"meN-"},
   {"no":4,"affix":"di-","type":"前缀","func":"被动语态标记：被……","rule":"di- + 及物动词；主语为受事，施事由 oleh 引出","derivs":[{"root":"sepakat","der":"disepakati","zh":"被商定"},{"root":"undang","der":"diundang","zh":"被邀请"},{"root":"siap","der":"disiapkan","zh":"被准备"},{"root":"tanda tangan","der":"ditandatangani","zh":"被签署"}],"examples":[{"id":"Jadwal final disepakati oleh kedua pihak.","cn":"最终日程经双方商定。"},{"id":"Kontrak akan ditandatangani pekan depan.","cn":"合同将于下周签署。"}],"link":"di-"},
   {"no":5,"affix":"ter-","type":"前缀","func":"表已然状态/完成；或构成最高级","rule":"ter- + 词根：表动作已完成的状态，无施事","derivs":[{"root":"capai","der":"tercapai","zh":"得以达成"},{"root":"cakup","der":"tercakup","zh":"被涵盖"},{"root":"laksana","der":"terlaksana","zh":"得以实施"},{"root":"utang","der":"terutang","zh":"被拖欠"}],"examples":[{"id":"Target produksi tahun ini sudah tercapai.","cn":"今年生产目标已达成。"},{"id":"Semua biaya pengiriman tercakup dalam penawaran.","cn":"所有运费都包含在报价中。"}],"link":"ter-"},
   {"no":6,"affix":"peN-","type":"前缀","func":"施事/工具名词：做……的人或物","rule":"peN- + 动词，同化规则同 meN-","derivs":[{"root":"tawar","der":"penawar","zh":"报价方"},{"root":"bicara","der":"pembicara","zh":"发言人"},{"root":"terima","der":"penerima","zh":"接收方"},{"root":"kirim","der":"pengirim","zh":"寄送方"}],"examples":[{"id":"Setiap penawar wajib mengajukan jaminan.","cn":"每位报价方须提交保证金。"},{"id":"Pembicara pertama dari pihak pembeli.","cn":"第一位发言人来自买方。"}],"link":"peN-"},
   {"no":7,"affix":"per-","type":"前缀","func":"表分配频率：每……；亦见于部分动词","rule":"per- + 单位名词/数量词；作动词前缀时表使成为","derivs":[{"root":"hari","der":"perhari","zh":"每天"},{"root":"bulan","der":"perbulan","zh":"每月"},{"root":"unit","der":"per unit","zh":"每单位"}],"examples":[{"id":"Biaya konsultan dihitung perhari.","cn":"顾问费按天计算。"},{"id":"Harga per unit belum termasuk ongkir.","cn":"单价不含运费。"}],"link":"per-"},
   {"no":8,"affix":"memper- / diper-","type":"前缀","func":"使役/强化：使更……；被动为 diper-","rule":"memper- + 形容词/动词；被动 diper- + 词根","derivs":[{"root":"jelas","der":"memperjelas","zh":"澄清"},{"root":"tegas","der":"mempertegas","zh":"强调"},{"root":"mudah","der":"mempermudah","zh":"简化"},{"root":"luas","der":"memperluas","zh":"扩大"}],"examples":[{"id":"Bolehkah Anda memperjelas pasal tentang denda?","cn":"能否请您澄清罚款条款？"},{"id":"Kami ingin mempermudah proses pembayaran.","cn":"我们希望简化付款流程。"}],"link":"memper- / diper-"},
   {"no":9,"affix":"se-","type":"前缀","func":"表数量一/相同/全体一致","rule":"se- + 名词/形容词：一个、同一、整个","derivs":[{"root":"pakat","der":"sepakat","zh":"一致同意"},{"root":"harga","der":"seharga","zh":"同价"},{"root":"jalan","der":"sejalan","zh":"方向一致"}],"examples":[{"id":"Kita sepakat soal jadwal pengiriman.","cn":"我们在交付期上意见一致。"},{"id":"Kebijakan baru sejalan dengan peraturan pemerintah.","cn":"新政策与政府法规保持一致。"}],"link":"se-"},
   {"no":10,"affix":"ke-","type":"前缀（方位）","func":"表方向：向/往；与部分词根合写表来去","rule":"ke- + 方位词/指示词，书面常分写；合写词需记忆","derivs":[{"root":"sini","der":"kesini","zh":"到这里"},{"root":"sana","der":"kesana","zh":"到那里"},{"root":"depan","der":"ke depan","zh":"向前/今后"}],"examples":[{"id":"Silakan berpindah ke ruang rapat utama.","cn":"请移步主会议室。"},{"id":"Untuk ke depan, kita sepakat bertemu bulanan.","cn":"今后我们约定每月会面。"}],"link":"ke-"}
